22	struct ContactInfo
23	{
24	    PhysicsShape* shapeA;
25	    PhysicsShape* shapeB;
26	    Vec2 contactPoints[4];
27	    Vec2 normal;
28	    float depths[4];
29	    int pointCount;
30	    float totalImpulse;
31	    bool isNew;
32	    bool isPersistent;
33	};
34	
35	typedef std::function<bool(const ContactInfo&)> ContactFilterFunc;
36	typedef std::function<void(const ContactInfo&)> ContactCallbackFunc;
37	
38	class PhysicsContactManager
39	{
40	public:
41	    PhysicsContactManager();
42	    ~PhysicsContactManager();
43	
44	    bool init(PhysicsWorld* world, int maxContacts = 256);
45	    void clear();
46	
47	    void processContacts(cpSpace* space);
48	    bool filterContact(PhysicsShape* shapeA, PhysicsShape* shapeB) const;
49	
50	    void addBeginCallback(ContactCallbackFunc callback);
51	    void addPreSolveCallback(ContactCallbackFunc callback);
52	    void addPostSolveCallback(ContactCallbackFunc callback);
53	    void addSeparateCallback(ContactCallbackFunc callback);
54	    void setContactFilter(ContactFilterFunc filter);
55	
56	    int getContactCount() const;
57	    int getActiveContactCount() const;
58	    const ContactInfo* getContact(int index) const;
59	    const ContactInfo* findContactBetween(PhysicsBody* bodyA, PhysicsBody* bodyB) const;
60	
61	    bool isContactActive(PhysicsShape* shapeA, PhysicsShape* shapeB) const;
62	    Vec2 getContactNormal(int index) const;
63	    float getContactDepth(int index) const;
64	    float getTotalImpulse(int index) const;
65	
66	    void setMaxContacts(int max);
67	    int getMaxContacts() const;
68	
69	    void dispatchBeginEvent(const ContactInfo& info);
70	    void dispatchPreSolveEvent(const ContactInfo& info);
71	    void dispatchPostSolveEvent(const ContactInfo& info);
72	    void dispatchSeparateEvent(const ContactInfo& info);
73	
74	private:
75	    PhysicsWorld* _world;
76	    std::vector<ContactInfo> _contacts;
77	    std::vector<ContactCallbackFunc> _beginCallbacks;
78	    std::vector<ContactCallbackFunc> _preSolveCallbacks;
79	    std::vector<ContactCallbackFunc> _postSolveCallbacks;
80	    std::vector<ContactCallbackFunc> _separateCallbacks;
81	    ContactFilterFunc _customFilter;
82	    int _maxContacts;
83	    bool _initialized;
84	};
85	
86	NS_CC_END
87	
88	#endif // CC_USE_PHYSICS
89	#endif // __CC_PHYSICS_CONTACT_MANAGER_H__
