29	bool PhysicsCollisionPair::init(cpArbiter* arbiter)
30	{
31	    if (arbiter == nullptr)
32	    {
33	        return false;
34	    }
35	
36	    cpShape* cpShapeA = nullptr;
37	    cpShape* cpShapeB = nullptr;
38	    cpArbiterGetShapes(arbiter, &cpShapeA, &cpShapeB);
39	
40	    if (cpShapeA == nullptr || cpShapeB == nullptr)
41	    {
42	        return false;
43	    }
44	
45	    PhysicsShape* shapeA = static_cast<PhysicsShape*>(cpShapeGetUserData(cpShapeA));
46	    PhysicsShape* shapeB = static_cast<PhysicsShape*>(cpShapeGetUserData(cpShapeB));
47	
48	    if (shapeA == nullptr || shapeB == nullptr)
49	    {
50	        return false;
51	    }
52	
53	    _arbiter = arbiter;
54	    _shapeA = shapeA;
55	    _shapeB = shapeB;
56	    _valid = true;
57	    _ignored = false;
58	
59	    return true;
60	}
61	
62	void PhysicsCollisionPair::update(cpArbiter* arbiter)
63	{
