    // ContactInfo::contactPoints and ::depths are fixed size arrays. Chipmunk never reports
    // more than CP_MAX_CONTACTS_PER_ARBITER (2) points per arbiter, so this is a hard bound.
    const int kMaxContactPoints = 4;

    // init() reserves the contact cache up front, but a caller may pass a very large cap;
    // only this many slots are pre-allocated, the rest grow on demand.
    const size_t kMaxReservedContacts = 4096;

    // The collision handler installed on a cpSpace stores a raw manager pointer and chipmunk
    // has no API to remove a default handler again, so every initialised manager is tracked
    // here and the handler thunks refuse to dereference a manager that is no longer live.
    std::vector<PhysicsContactManager*>& liveManagers()
    {
        static std::vector<PhysicsContactManager*> managers;
        return managers;
    }

    bool isLiveManager(PhysicsContactManager* manager)
    {
        const std::vector<PhysicsContactManager*>& managers = liveManagers();
        return std::find(managers.begin(), managers.end(), manager) != managers.end();
    }

    void registerManager(PhysicsContactManager* manager)
    {
        if (manager == nullptr || isLiveManager(manager))
        {
            return;
        }

        liveManagers().push_back(manager);
    }

    void unregisterManager(PhysicsContactManager* manager)
    {
        std::vector<PhysicsContactManager*>& managers = liveManagers();
        std::vector<PhysicsContactManager*>::iterator it = std::find(managers.begin(), managers.end(), manager);
        if (it != managers.end())
        {
            managers.erase(it);
        }
    }

    PhysicsContactManager* managerFromData(cpDataPointer data)
    {
        PhysicsContactManager* manager = static_cast<PhysicsContactManager*>(data);
        return (manager != nullptr && isLiveManager(manager)) ? manager : nullptr;
    }

    // PhysicsWorld::_cpSpace is not reachable from this module, so the space is taken from the
    // first body that is actually simulated. A world that is still empty resolves to nullptr,
    // which is why every caller re-resolves instead of caching the result once.
    cpSpace* resolveSpace(PhysicsWorld* world)
    {
        if (world == nullptr)
        {
            return nullptr;
        }

        const Vector<PhysicsBody*>& bodies = world->getAllBodies();
        for (const auto& body : bodies)
        {
            if (body == nullptr)
            {
                continue;
            }

            cpBody* rawBody = body->getCPBody();
            if (rawBody == nullptr)
            {
                continue;
            }

            cpSpace* space = cpBodyGetSpace(rawBody);
            if (space != nullptr)
            {
                return space;
            }
        }

        return nullptr;
    }

    void resetContactInfo(ContactInfo& info)
    {
        info.shapeA = nullptr;
        info.shapeB = nullptr;
        for (int i = 0; i < kMaxContactPoints; ++i)
        {
            info.contactPoints[i] = Vec2::ZERO;
            info.depths[i] = 0.0f;
        }
        info.normal = Vec2::ZERO;
        info.pointCount = 0;
        info.totalImpulse = 0.0f;
        info.isNew = false;
        info.isPersistent = false;
    }

    // Fills every field of info from the arbiter. Returns false when the arbiter does not map
    // onto a pair of cocos shapes, in which case info is left fully zeroed.
    bool buildContactInfo(cpArbiter* arbiter, ContactInfo& info)
    {
        resetContactInfo(info);

        if (arbiter == nullptr)
        {
            return false;
        }

        cpShape* rawShapeA = nullptr;
        cpShape* rawShapeB = nullptr;
        cpArbiterGetShapes(arbiter, &rawShapeA, &rawShapeB);
        if (rawShapeA == nullptr || rawShapeB == nullptr)
        {
            return false;
        }

        PhysicsShape* shapeA = static_cast<PhysicsShape*>(cpShapeGetUserData(rawShapeA));
        PhysicsShape* shapeB = static_cast<PhysicsShape*>(cpShapeGetUserData(rawShapeB));
        if (shapeA == nullptr || shapeB == nullptr)
        {
            return false;
        }

        info.shapeA = shapeA;
        info.shapeB = shapeB;
        info.normal = PhysicsHelper::cpv2point(cpArbiterGetNormal(arbiter));

        // Zero during a separate callback, at most CP_MAX_CONTACTS_PER_ARBITER otherwise.
        int count = cpArbiterGetCount(arbiter);
        if (count < 0)
        {
            count = 0;
        }
        if (count > kMaxContactPoints)
        {
            count = kMaxContactPoints;
        }

        for (int i = 0; i < count; ++i)
        {
            // The two surface points differ by the penetration, so the manifold point is
            // reported half way between them.
            Vec2 pointA = PhysicsHelper::cpv2point(cpArbiterGetPointA(arbiter, i));
            Vec2 pointB = PhysicsHelper::cpv2point(cpArbiterGetPointB(arbiter, i));
            info.contactPoints[i] = (pointA + pointB) * 0.5f;

            // cpArbiterGetDepth() is a signed separation: negative while the shapes overlap.
            info.depths[i] = std::fabs(PhysicsHelper::cpfloat2float(cpArbiterGetDepth(arbiter, i)));
        }

        info.pointCount = count;
        info.totalImpulse = PhysicsHelper::cpfloat2float(cpvlength(cpArbiterTotalImpulse(arbiter)));
        info.isNew = cpArbiterIsFirstContact(arbiter) != 0;
        info.isPersistent = !info.isNew && cpArbiterIsRemoval(arbiter) == 0;

        return true;
    }

    // The contactTest bitmasks decide whether a pair is *reported*; collision is decided by the
    // category/collision bitmasks in PhysicsContactManager::filterContact().
    bool shouldReportContact(PhysicsShape* shapeA, PhysicsShape* shapeB)
    {
        if (shapeA == nullptr || shapeB == nullptr)
        {
            return false;
        }

        const int categoryA = shapeA->getCategoryBitmask();
        const int categoryB = shapeB->getCategoryBitmask();
        const int testA = shapeA->getContactTestBitmask();
        const int testB = shapeB->getContactTestBitmask();

        return ((categoryA & testB) | (categoryB & testA)) != 0;
    }

    // Invokes every callback in registration order. The loop is index based and re-reads the
    // container size, so a callback may register another callback without invalidating it.
    void invokeCallbacks(const std::vector<ContactCallbackFunc>& callbacks, const ContactInfo& info)
    {
        for (size_t i = 0; i < callbacks.size(); ++i)
        {
            ContactCallbackFunc callback = callbacks[i];
            if (callback)
            {
                callback(info);
            }
        }
    }

    struct ArbiterCollector
    {
        std::vector<cpArbiter*> arbiters;
    };

    void collectArbiter(cpBody* /*body*/, cpArbiter* arbiter, void* data)
    {
        ArbiterCollector* collector = static_cast<ArbiterCollector*>(data);
        if (collector == nullptr || arbiter == nullptr)
        {
            return;
        }

        // An arbiter is linked into the list of both of its bodies, so a pair shared by two
        // bodies is seen twice. Identity is only used for de-duplication, never for ordering.
        if (std::find(collector->arbiters.begin(), collector->arbiters.end(), arbiter) != collector->arbiters.end())
        {
            return;
        }

        collector->arbiters.push_back(arbiter);
    }

    void collectBodyArbiters(cpBody* body, void* data)
    {
        if (body == nullptr || data == nullptr)
        {
            return;
        }

        cpBodyEachArbiter(body, collectArbiter, data);
    }

    cpBool contactBeginFunc(cpArbiter* arbiter, cpSpace* /*space*/, cpDataPointer data)
    {
        PhysicsContactManager* manager = managerFromData(data);
        if (manager == nullptr)
        {
            return cpTrue;
        }

        ContactInfo info;
        if (!buildContactInfo(arbiter, info))
        {
            return cpTrue;
        }

        if (!manager->filterContact(info.shapeA, info.shapeB))
        {
            return cpFalse;
        }

        // A begin callback is by definition the first step in which this pair touches.
        info.isNew = true;
        info.isPersistent = false;

        if (shouldReportContact(info.shapeA, info.shapeB))
        {
            manager->dispatchBeginEvent(info);
        }

        return cpTrue;
    }

    cpBool contactPreSolveFunc(cpArbiter* arbiter, cpSpace* /*space*/, cpDataPointer data)
    {
        PhysicsContactManager* manager = managerFromData(data);
        if (manager == nullptr)
        {
            return cpTrue;
        }

        ContactInfo info;
        if (!buildContactInfo(arbiter, info))
        {
            return cpTrue;
        }

        if (!manager->filterContact(info.shapeA, info.shapeB))
        {
            return cpFalse;
        }

        if (shouldReportContact(info.shapeA, info.shapeB))
        {
            manager->dispatchPreSolveEvent(info);
        }

        return cpTrue;
    }

    void contactPostSolveFunc(cpArbiter* arbiter, cpSpace* /*space*/, cpDataPointer data)
    {
        PhysicsContactManager* manager = managerFromData(data);
        if (manager == nullptr)
        {
            return;
        }

        ContactInfo info;
        if (!buildContactInfo(arbiter, info))
        {
            return;
        }

        if (!manager->filterContact(info.shapeA, info.shapeB))
        {
            return;
        }

        if (shouldReportContact(info.shapeA, info.shapeB))
        {
            // Impulses are only meaningful once the solver has run, which is the case here.
            manager->dispatchPostSolveEvent(info);
        }
    }

    void contactSeparateFunc(cpArbiter* arbiter, cpSpace* /*space*/, cpDataPointer data)
    {
        PhysicsContactManager* manager = managerFromData(data);
        if (manager == nullptr)
        {
            return;
        }

        ContactInfo info;
        if (!buildContactInfo(arbiter, info))
        {
            return;
        }

        if (!manager->filterContact(info.shapeA, info.shapeB))
        {
            return;
        }

        // The pair is going away: it is neither new nor persistent any more, and chipmunk
        // already reports zero contact points during a separate callback.
        info.isNew = false;
        info.isPersistent = false;

        if (shouldReportContact(info.shapeA, info.shapeB))
        {
            manager->dispatchSeparateEvent(info);
        }
    }

    // Idempotent: chipmunk hands out one default handler per space, so re-installing only
    // rewrites the thunks when the space is not already routed to this manager.
    bool installHandler(cpSpace* space, PhysicsContactManager* manager)
    {
        if (space == nullptr || manager == nullptr)
        {
            return false;
        }

        cpCollisionHandler* handler = cpSpaceAddDefaultCollisionHandler(space);
        if (handler == nullptr)
        {
            return false;
        }

        if (handler->userData == manager)
        {
            return true;
        }

        handler->userData = manager;
        handler->beginFunc = contactBeginFunc;
        handler->preSolveFunc = contactPreSolveFunc;
        handler->postSolveFunc = contactPostSolveFunc;
        handler->separateFunc = contactSeparateFunc;

        return true;
    }
}

PhysicsContactManager::PhysicsContactManager()
: _world(nullptr)
, _maxContacts(256)
, _initialized(false)
{
}

PhysicsContactManager::~PhysicsContactManager()
{
    // Leaving the live registry is what makes the handler thunks safe: the cpSpace keeps the
    // raw manager pointer and chipmunk cannot restore its own default handler funcs.
    unregisterManager(this);

    _contacts.clear();
    _beginCallbacks.clear();
    _preSolveCallbacks.clear();
    _postSolveCallbacks.clear();
    _separateCallbacks.clear();
    _customFilter = nullptr;
    _world = nullptr;
    _initialized = false;
}

bool PhysicsContactManager::init(PhysicsWorld* world, int maxContacts)
{
    CCASSERT(world != nullptr, "the world can not be nullptr");
    if (world == nullptr)
    {
        return false;
    }

    _world = world;
    _maxContacts = maxContacts < 0 ? 0 : maxContacts;

    _contacts.clear();
    size_t reserved = static_cast<size_t>(_maxContacts);
    if (reserved > kMaxReservedContacts)
    {
        reserved = kMaxReservedContacts;
    }
    if (reserved > 0)
    {
        _contacts.reserve(reserved);
    }

    registerManager(this);
    _initialized = true;

    // The cpSpace only becomes reachable once the world holds a simulated body; a world that is
    // still empty gets its handler installed by the first processContacts() call instead.
    cpSpace* space = resolveSpace(_world);
    if (space != nullptr)
    {
        installHandler(space, this);
    }

    return true;
}

void PhysicsContactManager::clear()
{
    // Only the per-step contact cache is dropped. Registered callbacks and the custom filter
    // stay alive so the manager keeps reporting after the next step.
    _contacts.clear();
}

void PhysicsContactManager::processContacts(cpSpace* space)
{
    cpSpace* target = space != nullptr ? space : resolveSpace(_world);
    if (target == nullptr)
    {
        return;
    }

    // Late installation for a world that had no body in a space when init() ran. Handler funcs
    // are never rewritten while the space is stepping.
    if (_initialized && !cpSpaceIsLocked(target))
    {
        installHandler(target, this);
    }

    _contacts.clear();
    if (_maxContacts <= 0)
    {
        return;
    }

    // cpSpaceEachBody() locks the space, so the arbiters are only gathered inside the walk and
    // decoded afterwards. That also means the shape order comes from the arbiter itself rather
    // than from whichever body happened to be visited first.
    ArbiterCollector collector;
    cpSpaceEachBody(target, collectBodyArbiters, &collector);

    for (size_t i = 0; i < collector.arbiters.size(); ++i)
    {
        if (static_cast<int>(_contacts.size()) >= _maxContacts)
        {
            break;
        }

        ContactInfo info;
        if (!buildContactInfo(collector.arbiters[i], info))
        {
            continue;
        }

        if (!filterContact(info.shapeA, info.shapeB))
        {
            continue;
        }

        _contacts.push_back(info);
    }
}

bool PhysicsContactManager::filterContact(PhysicsShape* shapeA, PhysicsShape* shapeB) const
{
    if (shapeA == nullptr || shapeB == nullptr || shapeA == shapeB)
    {
        return false;
    }

    PhysicsBody* bodyA = shapeA->getBody();
    PhysicsBody* bodyB = shapeB->getBody();
    if (bodyA == nullptr || bodyB == nullptr || bodyA == bodyB)
    {
        // Two shapes of the same body never collide with each other.
        return false;
    }

    const int groupA = shapeA->getGroup();
    const int groupB = shapeB->getGroup();
    if (groupA != 0 && groupA == groupB)
    {
        // Equal non-zero groups override the bitmasks: positive groups always collide,
        // negative groups never do.
        if (groupA < 0)
        {
            return false;
        }
    }
    else if ((shapeA->getCategoryBitmask() & shapeB->getCollisionBitmask()) == 0
             || (shapeB->getCategoryBitmask() & shapeA->getCollisionBitmask()) == 0)
    {
        return false;
    }

    if (_customFilter)
    {
        // Only the pair is known at filtering time - the manifold is not solved yet - so the
        // custom filter receives a fully zeroed ContactInfo carrying just the two shapes.
        ContactInfo info;
        resetContactInfo(info);
        info.shapeA = shapeA;
        info.shapeB = shapeB;

        if (!_customFilter(info))
        {
            return false;
        }
    }

    return true;
}

void PhysicsContactManager::addBeginCallback(ContactCallbackFunc callback)
{
    if (!callback)
    {
        return;
    }

    _beginCallbacks.push_back(std::move(callback));
}

void PhysicsContactManager::addPreSolveCallback(ContactCallbackFunc callback)
{
    if (!callback)
    {
        return;
    }

    _preSolveCallbacks.push_back(std::move(callback));
}

void PhysicsContactManager::addPostSolveCallback(ContactCallbackFunc callback)
{
    if (!callback)
    {
        return;
    }

    _postSolveCallbacks.push_back(std::move(callback));
}

void PhysicsContactManager::addSeparateCallback(ContactCallbackFunc callback)
{
    if (!callback)
    {
        return;
    }

    _separateCallbacks.push_back(std::move(callback));
}

void PhysicsContactManager::setContactFilter(ContactFilterFunc filter)
{
    // An empty filter is a valid argument: it clears the custom veto again.
    _customFilter = std::move(filter);
}

int PhysicsContactManager::getContactCount() const
{
    return static_cast<int>(_contacts.size());
}

int PhysicsContactManager::getActiveContactCount() const
{
    int active = 0;
    for (size_t i = 0; i < _contacts.size(); ++i)
    {
        if (_contacts[i].pointCount > 0)
        {
            ++active;
        }
    }

    return active;
}

const ContactInfo* PhysicsContactManager::getContact(int index) const
{
    if (index < 0 || index >= static_cast<int>(_contacts.size()))
    {
        return nullptr;
    }

    return &_contacts[static_cast<size_t>(index)];
}

const ContactInfo* PhysicsContactManager::findContactBetween(PhysicsBody* bodyA, PhysicsBody* bodyB) const
{
    if (bodyA == nullptr || bodyB == nullptr)
    {
        return nullptr;
    }

    for (size_t i = 0; i < _contacts.size(); ++i)
    {
        const ContactInfo& info = _contacts[i];
        if (info.shapeA == nullptr || info.shapeB == nullptr)
        {
            continue;
        }

        PhysicsBody* ownerA = info.shapeA->getBody();
        PhysicsBody* ownerB = info.shapeB->getBody();

        // The pair is unordered, so both assignments count as a match.
        if ((ownerA == bodyA && ownerB == bodyB) || (ownerA == bodyB && ownerB == bodyA))
        {
            return &_contacts[i];
        }
    }

    return nullptr;
}

bool PhysicsContactManager::isContactActive(PhysicsShape* shapeA, PhysicsShape* shapeB) const
{
    if (shapeA == nullptr || shapeB == nullptr)
    {
        return false;
    }

    for (size_t i = 0; i < _contacts.size(); ++i)
    {
        const ContactInfo& info = _contacts[i];
        const bool sameOrder = (info.shapeA == shapeA && info.shapeB == shapeB);
        const bool swapped = (info.shapeA == shapeB && info.shapeB == shapeA);

        // Active means the pair is in the cache *and* still holds a manifold point; a pair
        // that only touches its bounding boxes is recorded with pointCount == 0.
        if ((sameOrder || swapped) && info.pointCount > 0)
        {
            return true;
        }
    }

    return false;
}

Vec2 PhysicsContactManager::getContactNormal(int index) const
{
    const ContactInfo* info = getContact(index);
    if (info == nullptr)
    {
        return Vec2::ZERO;
    }

    return info->normal;
}

float PhysicsContactManager::getContactDepth(int index) const
{
    const ContactInfo* info = getContact(index);
    if (info == nullptr)
    {
        return 0.0f;
    }

    int count = info->pointCount;
    if (count > kMaxContactPoints)
    {
        count = kMaxContactPoints;
    }

    // The depth of a contact is the deepest of its manifold points.
    float depth = 0.0f;
    for (int i = 0; i < count; ++i)
    {
        if (info->depths[i] > depth)
        {
            depth = info->depths[i];
        }
    }

    return depth;
}

float PhysicsContactManager::getTotalImpulse(int index) const
{
    const ContactInfo* info = getContact(index);
    if (info == nullptr)
    {
        return 0.0f;
    }

    return info->totalImpulse;
}

void PhysicsContactManager::setMaxContacts(int max)
{
    _maxContacts = max < 0 ? 0 : max;

    if (static_cast<int>(_contacts.size()) > _maxContacts)
    {
        // Lowering the cap drops the contacts recorded past it; the surviving ones keep their
        // order so an index handed out earlier still refers to the same pair.
        _contacts.resize(static_cast<size_t>(_maxContacts));
    }
}

int PhysicsContactManager::getMaxContacts() const
{
    return _maxContacts;
}

void PhysicsContactManager::dispatchBeginEvent(const ContactInfo& info)
{
    invokeCallbacks(_beginCallbacks, info);
}

void PhysicsContactManager::dispatchPreSolveEvent(const ContactInfo& info)
{
    invokeCallbacks(_preSolveCallbacks, info);
}

void PhysicsContactManager::dispatchPostSolveEvent(const ContactInfo& info)
{
    invokeCallbacks(_postSolveCallbacks, info);
}

void PhysicsContactManager::dispatchSeparateEvent(const ContactInfo& info)
{
    invokeCallbacks(_separateCallbacks, info);
}

NS_CC_END

#endif // CC_USE_PHYSICS

