215	    struct ArbiterCollector
216	    {
217	        std::vector<cpArbiter*> arbiters;
218	    };
219	
220	    void collectArbiter(cpBody* /*body*/, cpArbiter* arbiter, void* data)
221	    {
222	        ArbiterCollector* collector = static_cast<ArbiterCollector*>(data);
223	        if (collector == nullptr || arbiter == nullptr)
224	        {
225	            return;
226	        }
227	
228	        // An arbiter is linked into the list of both of its bodies, so a pair shared by two
229	        // bodies is seen twice. Identity is only used for de-duplication, never for ordering.
230	        if (std::find(collector->arbiters.begin(), collector->arbiters.end(), arbiter) != collector->arbiters.end())
231	        {
232	            return;
233	        }
234	
235	        collector->arbiters.push_back(arbiter);
236	    }
237	
238	    void collectBodyArbiters(cpBody* body, void* data)
239	    {
240	        if (body == nullptr || data == nullptr)
241	        {
242	            return;
243	        }
244	
245	        cpBodyEachArbiter(body, collectArbiter, data);
246	    }
