248	    cpBool contactBeginFunc(cpArbiter* arbiter, cpSpace* /*space*/, cpDataPointer data)
249	    {
250	        PhysicsContactManager* manager = managerFromData(data);
251	        if (manager == nullptr)
252	        {
253	            return cpTrue;
254	        }
255	
256	        ContactInfo info;
257	        if (!buildContactInfo(arbiter, info))
258	        {
259	            return cpTrue;
260	        }
261	
262	        if (!manager->filterContact(info.shapeA, info.shapeB))
263	        {
264	            return cpFalse;
265	        }
266	
267	        // A begin callback is by definition the first step in which this pair touches.
268	        info.isNew = true;
269	        info.isPersistent = false;
270	
271	        if (shouldReportContact(info.shapeA, info.shapeB))
272	        {
273	            manager->dispatchBeginEvent(info);
274	        }
275	
276	        return cpTrue;
277	    }
278	
279	    cpBool contactPreSolveFunc(cpArbiter* arbiter, cpSpace* /*space*/, cpDataPointer data)
280	    {
281	        PhysicsContactManager* manager = managerFromData(data);
282	        if (manager == nullptr)
283	        {
284	            return cpTrue;
285	        }
286	
287	        ContactInfo info;
288	        if (!buildContactInfo(arbiter, info))
289	        {
290	            return cpTrue;
291	        }
292	
293	        if (!manager->filterContact(info.shapeA, info.shapeB))
294	        {
295	            return cpFalse;
296	        }
297	
298	        if (shouldReportContact(info.shapeA, info.shapeB))
299	        {
300	            manager->dispatchPreSolveEvent(info);
301	        }
302	
303	        return cpTrue;
304	    }
305	
306	    void contactPostSolveFunc(cpArbiter* arbiter, cpSpace* /*space*/, cpDataPointer data)
307	    {
308	        PhysicsContactManager* manager = managerFromData(data);
309	        if (manager == nullptr)
310	        {
311	            return;
312	        }
313	
314	        ContactInfo info;
315	        if (!buildContactInfo(arbiter, info))
316	        {
317	            return;
318	        }
319	
320	        if (!manager->filterContact(info.shapeA, info.shapeB))
321	        {
322	            return;
323	        }
324	
325	        if (shouldReportContact(info.shapeA, info.shapeB))
326	        {
327	            // Impulses are only meaningful once the solver has run, which is the case here.
328	            manager->dispatchPostSolveEvent(info);
329	        }
330	    }
331	
332	    void contactSeparateFunc(cpArbiter* arbiter, cpSpace* /*space*/, cpDataPointer data)
333	    {
334	        PhysicsContactManager* manager = managerFromData(data);
335	        if (manager == nullptr)
336	        {
337	            return;
338	        }
339	
340	        ContactInfo info;
341	        if (!buildContactInfo(arbiter, info))
342	        {
343	            return;
344	        }
345	
346	        if (!manager->filterContact(info.shapeA, info.shapeB))
347	        {
348	            return;
349	        }
350	
351	        // The pair is going away: it is neither new nor persistent any more, and chipmunk
352	        // already reports zero contact points during a separate callback.
353	        info.isNew = false;
354	        info.isPersistent = false;
355	
356	        if (shouldReportContact(info.shapeA, info.shapeB))
357	        {
358	            manager->dispatchSeparateEvent(info);
359	        }
360	    }
361	
362	    // Idempotent: chipmunk hands out one default handler per space, so re-installing only
363	    // rewrites the thunks when the space is not already routed to this manager.
364	    bool installHandler(cpSpace* space, PhysicsContactManager* manager)
365	    {
366	        if (space == nullptr || manager == nullptr)
367	        {
368	            return false;
369	        }
370	
371	        cpCollisionHandler* handler = cpSpaceAddDefaultCollisionHandler(space);
372	        if (handler == nullptr)
373	        {
374	            return false;
375	        }
376	
377	        if (handler->userData == manager)
378	        {
379	            return true;
380	        }
381	
382	        handler->userData = manager;
383	        handler->beginFunc = contactBeginFunc;
384	        handler->preSolveFunc = contactPreSolveFunc;
385	        handler->postSolveFunc = contactPostSolveFunc;
386	        handler->separateFunc = contactSeparateFunc;
387	
388	        return true;
389	    }
390	}
