415	bool PhysicsContactManager::init(PhysicsWorld* world, int maxContacts)
416	{
417	    CCASSERT(world != nullptr, "the world can not be nullptr");
418	    if (world == nullptr)
419	    {

415	bool PhysicsContactManager::init(PhysicsWorld* world, int maxContacts)
416	{
417	    CCASSERT(world != nullptr, "the world can not be nullptr");
418	    if (world == nullptr)
419	    {
420	        return false;
421	    }
422	
423	    _world = world;
424	    _maxContacts = maxContacts < 0 ? 0 : maxContacts;
425	
426	    _contacts.clear();
427	    size_t reserved = static_cast<size_t>(_maxContacts);
428	    if (reserved > kMaxReservedContacts)
429	    {
430	        reserved = kMaxReservedContacts;
431	    }
432	    if (reserved > 0)
433	    {
434	        _contacts.reserve(reserved);
435	    }
436	
437	    registerManager(this);
438	    _initialized = true;
439	
440	    // The cpSpace only becomes reachable once the world holds a simulated body; a world that is
441	    // still empty gets its handler installed by the first processContacts() call instead.
442	    cpSpace* space = resolveSpace(_world);
443	    if (space != nullptr)
444	    {
445	        installHandler(space, this);
446	    }
447	
448	    return true;
449	}
