458	void PhysicsContactManager::processContacts(cpSpace* space)
459	{
460	    cpSpace* target = space != nullptr ? space : resolveSpace(_world);
461	    if (target == nullptr)
462	    {
463	        return;
464	    }
465	
466	    // Late installation for a world that had no body in a space when init() ran. Handler funcs
467	    // are never rewritten while the space is stepping.
468	    if (_initialized && !cpSpaceIsLocked(target))
469	    {
470	        installHandler(target, this);
471	    }
472	
473	    _contacts.clear();
474	    if (_maxContacts <= 0)
475	    {
476	        return;
477	    }
478	
479	    // cpSpaceEachBody() locks the space, so the arbiters are only gathered inside the walk and
480	    // decoded afterwards. That also means the shape order comes from the arbiter itself rather
481	    // than from whichever body happened to be visited first.
482	    ArbiterCollector collector;
483	    cpSpaceEachBody(target, collectBodyArbiters, &collector);
484	
485	    for (size_t i = 0; i < collector.arbiters.size(); ++i)
486	    {
487	        if (static_cast<int>(_contacts.size()) >= _maxContacts)
488	        {
489	            break;
490	        }
491	
492	        ContactInfo info;
493	        if (!buildContactInfo(collector.arbiters[i], info))
494	        {
495	            continue;
496	        }
497	
498	        if (!filterContact(info.shapeA, info.shapeB))
499	        {
500	            continue;
501	        }
502	
503	        _contacts.push_back(info);
504	    }
505	}
