632	const ContactInfo* PhysicsContactManager::findContactBetween(PhysicsBody* bodyA, PhysicsBody* bodyB) const
633	{
634	    if (bodyA == nullptr || bodyB == nullptr)
635	    {
636	        return nullptr;
637	    }
638	
639	    for (size_t i = 0; i < _contacts.size(); ++i)
640	    {
641	        const ContactInfo& info = _contacts[i];
642	        if (info.shapeA == nullptr || info.shapeB == nullptr)
643	        {
644	            continue;
645	        }
646	
647	        PhysicsBody* ownerA = info.shapeA->getBody();
648	        PhysicsBody* ownerB = info.shapeB->getBody();
649	
650	        // The pair is unordered, so both assignments count as a match.
651	        if ((ownerA == bodyA && ownerB == bodyB) || (ownerA == bodyB && ownerB == bodyA))
652	        {
653	            return &_contacts[i];
654	        }
655	    }
656	
657	    return nullptr;
658	}
