660	bool PhysicsContactManager::isContactActive(PhysicsShape* shapeA, PhysicsShape* shapeB) const
661	{
662	    if (shapeA == nullptr || shapeB == nullptr)
663	    {
664	        return false;
665	    }
666	
667	    for (size_t i = 0; i < _contacts.size(); ++i)
668	    {
669	        const ContactInfo& info = _contacts[i];
670	        const bool sameOrder = (info.shapeA == shapeA && info.shapeB == shapeB);
671	        const bool swapped = (info.shapeA == shapeB && info.shapeB == shapeA);
672	
673	        // Active means the pair is in the cache *and* still holds a manifold point; a pair
674	        // that only touches its bounding boxes is recorded with pointCount == 0.
675	        if ((sameOrder || swapped) && info.pointCount > 0)
676	        {
677	            return true;
678	        }
679	    }
680	
681	    return false;
682	}
