695	float PhysicsContactManager::getContactDepth(int index) const
696	{
697	    const ContactInfo* info = getContact(index);
698	    if (info == nullptr)
699	    {
700	        return 0.0f;
701	    }
702	
703	    int count = info->pointCount;
704	    if (count > kMaxContactPoints)
705	    {
706	        count = kMaxContactPoints;
707	    }
708	
709	    // The depth of a contact is the deepest of its manifold points.
710	    float depth = 0.0f;
711	    for (int i = 0; i < count; ++i)
712	    {
713	        if (info->depths[i] > depth)
714	        {
715	            depth = info->depths[i];
716	        }
717	    }
718	
719	    return depth;
720	}
